   131	// killPinnedMarkedProcess signals pid only through a pidfd opened on it,
   132	// after the environment read through that same pinned process still holds
   133	// entry.
   134	func killPinnedMarkedProcess(pid int, entry []byte) error {
   135		fd, err := unix.PidfdOpen(pid, 0)
   136		if errors.Is(err, unix.ESRCH) {
   137			return nil
   138		}
   139		if err != nil {
   140			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   141		}
   142		defer unix.Close(fd)
   143		// The pidfd names one process for its lifetime; if pid was reused before
   144		// it was opened, the new process does not carry this run's entry.
   145		marked, err := reviewProcessMarked(pid, entry)
   146		if reviewProcessGoneErr(err) || err == nil && !marked {
   147			return nil
   148		}
   149		if err != nil {
   150			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
   151		}
   152		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
   153			return fmt.Errorf("process %d could not be ended: %w", pid, err)
   154		}
   155		return nil
   156	}
