   171	func reviewProcessOwner(pid int) (int, error) {
   172		info, err := os.Stat(filepath.Join("/proc", strconv.Itoa(pid)))
   173		if err != nil {
   174			return 0, err
   175		}
   176		st, ok := info.Sys().(*syscall.Stat_t)
   177		if !ok {
   178			return 0, fmt.Errorf("process %d owner unavailable", pid)
   179		}
   180		return int(st.Uid), nil
   181	}
