   195	func reviewProcessZombie(pid int) (bool, error) {
   196		raw, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
   197		if err != nil {
   198			return false, err
   199		}
   200		// The state follows the parenthesised command name.
   201		if i := bytes.LastIndexByte(raw, ')'); i >= 0 && i+2 < len(raw) {
   202			return raw[i+2] == 'Z', nil
   203		}
   204		return false, fmt.Errorf("process %d state is unreadable", pid)
   205	}
